import { importProvidersFrom } from '@angular/core';
import { provideRouter } from '@angular/router';
import { provideHttpClient } from '@angular/common/http';
import { BrowserAnimationsModule } from '@angular/platform-browser/animations'; // Required for Material
const routes = [{
  path: '',
  // This lazy loads your VehicleModule when the user hits the base URL
  loadChildren: () => import('./vehicle/vehicle.module').then(m => m.VehicleModule)
}, {
  path: '**',
  redirectTo: ''
} // Redirect unknown paths to home
];

export const appConfig = {
  providers: [provideRouter(routes), provideHttpClient(),
  // Important: Material Design and NgxLoading often require animations
  importProvidersFrom(BrowserAnimationsModule)]
};
